$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$root = (Get-Location).Path

$packagePath = Join-Path $root "package.json"
$navigationPath = Join-Path $root "data\navigation.ts"
$productSelectionPath = Join-Path $root "components\products\selection\ProductSelectionClient.tsx"
$zhProductsPagePath = Join-Path $root "app\products\page.tsx"
$localeProductsPagePath = Join-Path $root "app\[locale]\products\page.tsx"

$requiredPaths = @(
  $packagePath,
  $navigationPath,
  $productSelectionPath,
  $zhProductsPagePath,
  $localeProductsPagePath
)

foreach ($requiredPath in $requiredPaths) {
  if (-not (Test-Path -LiteralPath $requiredPath)) {
    throw "没有找到必要文件：$requiredPath"
  }
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupMap = @{}

function Backup-File {
  param([string]$Path)

  $backupPath = $Path + "." + $stamp + ".bak"
  Copy-Item -LiteralPath $Path -Destination $backupPath -Force
  $script:backupMap[$Path] = $backupPath
  Write-Host "已备份：$backupPath" -ForegroundColor Yellow
}

function Write-Utf8NoBom {
  param(
    [string]$Path,
    [string]$Content
  )

  $encoding = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($Path, $Content, $encoding)
}

function Decode-Base64Utf8 {
  param([string]$Encoded)

  $bytes = [System.Convert]::FromBase64String($Encoded)
  return [System.Text.Encoding]::UTF8.GetString($bytes)
}

try {
  Backup-File -Path $navigationPath
  Backup-File -Path $productSelectionPath
  Backup-File -Path $zhProductsPagePath
  Backup-File -Path $localeProductsPagePath

  $navigationBase64 = @'

'@

  $productSelectionBase64 = @'

'@

  $navigationContent = Decode-Base64Utf8 -Encoded ($navigationBase64.Trim())
  $productSelectionContent = Decode-Base64Utf8 -Encoded ($productSelectionBase64.Trim())

  Write-Utf8NoBom -Path $navigationPath -Content $navigationContent
  Write-Utf8NoBom -Path $productSelectionPath -Content $productSelectionContent

  Write-Host ""
  Write-Host "已更新导航与产品中心参数读取逻辑。" -ForegroundColor Green

  $zhPageContent = Get-Content -LiteralPath $zhProductsPagePath -Raw -Encoding UTF8

  if ($zhPageContent -notmatch 'import\s+\{\s*Suspense\s*\}\s+from\s+["'']react["'']') {
    $zhPageContent = $zhPageContent.Replace(
      'import ProductSelectionClient from "@/components/products/selection/ProductSelectionClient";',
      'import { Suspense } from "react";' + [Environment]::NewLine + [Environment]::NewLine + 'import ProductSelectionClient from "@/components/products/selection/ProductSelectionClient";'
    )
  }

  $zhPagePattern = 'export default function ProductsPage\(\)\s*\{\s*return\s+<ProductSelectionClient\s+locale=["'']zh["'']\s*/>;\s*\}'
  $zhPageReplacement = @'
export default function ProductsPage() {
  return (
    <Suspense fallback={null}>
      <ProductSelectionClient locale="zh" />
    </Suspense>
  );
}
'@

  if (-not [Regex]::IsMatch($zhPageContent, $zhPagePattern)) {
    throw "无法在中文产品中心页面中找到 ProductSelectionClient 返回结构。"
  }

  $zhPageContent = [Regex]::Replace(
    $zhPageContent,
    $zhPagePattern,
    $zhPageReplacement.Trim(),
    1
  )

  Write-Utf8NoBom -Path $zhProductsPagePath -Content $zhPageContent

  $localePageContent = Get-Content -LiteralPath $localeProductsPagePath -Raw -Encoding UTF8

  if ($localePageContent -notmatch 'import\s+\{\s*Suspense\s*\}\s+from\s+["'']react["'']') {
    $localePageContent = $localePageContent.Replace(
      'import { notFound } from "next/navigation";',
      'import { Suspense } from "react";' + [Environment]::NewLine + 'import { notFound } from "next/navigation";'
    )
  }

  $localeReturnPattern = 'return\s+<ProductSelectionClient\s+locale=\{productSelectionLocale\}\s*/>;'
  $localeReturnReplacement = @'
return (
    <Suspense fallback={null}>
      <ProductSelectionClient locale={productSelectionLocale} />
    </Suspense>
  );
'@

  if (-not [Regex]::IsMatch($localePageContent, $localeReturnPattern)) {
    throw "无法在多语言产品中心页面中找到 ProductSelectionClient 返回结构。"
  }

  $localePageContent = [Regex]::Replace(
    $localePageContent,
    $localeReturnPattern,
    $localeReturnReplacement.Trim(),
    1
  )

  Write-Utf8NoBom -Path $localeProductsPagePath -Content $localePageContent

  $nextPath = Join-Path $root ".next"

  if (Test-Path -LiteralPath $nextPath) {
    Remove-Item -LiteralPath $nextPath -Recurse -Force
    Write-Host "已清理 .next 缓存。" -ForegroundColor Yellow
  }

  Write-Host ""
  Write-Host "正在运行 npm run build……" -ForegroundColor Cyan

  & npm run build

  if ($LASTEXITCODE -ne 0) {
    throw "构建失败。"
  }

  Write-Host ""
  Write-Host "执行完成：" -ForegroundColor Green
  Write-Host " - 产品中心一级导航 → /products"
  Write-Host " - 泵类入口 → /products?category=pumps"
  Write-Host " - 柱塞泵入口 → /products?category=pumps&productType=plunger-pump"
  Write-Host " - 多语言路径自动保留 /en、/es、/fr、/ko、/ru"
  Write-Host " - 产品中心会根据 URL 自动选中泵系列与柱塞泵"
  Write-Host " - npm run build 已通过"
}
catch {
  Write-Host ""
  Write-Host "执行失败：$($_.Exception.Message)" -ForegroundColor Red
  Write-Host "正在恢复本次修改……" -ForegroundColor Yellow

  foreach ($path in $backupMap.Keys) {
    $backupPath = $backupMap[$path]

    if (Test-Path -LiteralPath $backupPath) {
      Copy-Item -LiteralPath $backupPath -Destination $path -Force
    }
  }

  Write-Host "文件已恢复。" -ForegroundColor Yellow
  throw
}
